for id,title,statement,evidence,controls in [
('PFPDOMAIN-F012','Byte-exact compilation receipt does not bind semantic role letters','A constraint span with exact bytes/digest/coverage is accepted with task-letter q or unsupported letter z in BoundaryWire. The regex permits every lowercase letter and receipt validation checks symbol count/order/ranges/text but never compares role annotations. Its byte-preservation guarantee survives this counterexample; interpreting the receipt as preserving role semantics does not.',[ev('pfp/domain/rewriting/rewriting_types.py',(23,24),(104,118),(147,167))],['PFPDOMAIN-C016']),
('PFPDOMAIN-F013','Wire codec loses recursive AST structure and has noninjective rendering','A nested App f(App g(Atom x)) renders (f (g x)) but the parser makes two atom arguments, so parse(serialize(term)) differs from term for an admitted recursive model. Atom value () and Void render identically. No escaping, recursive tokenization or profile budget enforcement repairs this in WireCodec.',[ev('pfp/domain/rewriting/wires.py',(21,49),(94,118))],['PFPDOMAIN-C017'])]:
 n['findings'].append({'id':id,'title':title,'statement':statement,'evidence':[x['path'] for x in evidence],'source_evidence':evidence,'control_ids':controls,'status':'confirmed_bounded_source_and_probe','limits':'Python3.14.2/Pydantic2.13.5 controls over source-loaded owners; no whole application or model behavior claim.'})
n['claims'].append({'id':'PFPDOMAIN-CL05','title':'Boundary grammar, byte custody and semantic fidelity are separate contracts','statement':'parse_boundary refuses empty <> and proves only membership in its bounded nonempty ASCII tree grammar. CompilationReceipt supplies a useful exact byte-cover/hash/codebook mechanism, conditional on caller-chosen spans, but does not prove semantic labels or question equivalence. ExpansionNode proves finite occurrence counts and depth, not that decomposed prompts preserve a task. Wiki/spec dialect comparisons remain documentation claims owned by the parent audit.','evidence':['pfp/domain/rewriting/rewrites.py','pfp/domain/rewriting/rewriting_types.py','pfp/domain/rewriting/prompt_containment.py'],'source_evidence':[ev('pfp/domain/rewriting/rewrites.py',(39,80)),ev('pfp/domain/rewriting/rewriting_types.py',(74,101),(137,167)),ev('pfp/domain/rewriting/prompt_containment.py',(57,68))],'control_ids':['PFPDOMAIN-C015','PFPDOMAIN-C016'],'status':'bounded_scope_assessment'})
